public class FoldsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("sum of 1..5", 15,
                    Folds.foldLeft(java.util.List.of(1, 2, 3, 4, 5), 0,
                            (acc, n) -> acc + n));
            check("string concatenation", "abc",
                    Folds.foldLeft(java.util.List.of("a", "b", "c"), "",
                            (acc, s) -> acc + s));
            check("seed is the starting value", "<abc",
                    Folds.foldLeft(java.util.List.of("a", "b", "c"), "<",
                            (acc, s) -> acc + s));
            check("max via Math::max", 9,
                    Folds.foldLeft(java.util.List.of(3, 9, 2, 7), Integer.MIN_VALUE,
                            Math::max));
            check("left-to-right order (digits build 123)", 123,
                    Folds.foldLeft(java.util.List.of(1, 2, 3), 0,
                            (acc, n) -> acc * 10 + n));
            check("empty list returns the seed", 42,
                    Folds.foldLeft(java.util.List.<Integer>of(), 42, (acc, n) -> acc + n));
            check("fold to a different result type (count chars)", 6,
                    Folds.foldLeft(java.util.List.of("ab", "cde", "f"), 0,
                            (acc, s) -> acc + s.length()));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e.getClass().getSimpleName());
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
