public class Folds {

    public static <T, R> R foldLeft(java.util.List<T> items, R seed,
            java.util.function.BiFunction<R, T, R> f) {
        R acc = seed;
        for (T item : items) {
            acc = f.apply(acc, item);
        }
        return acc;
    }
}
